('funk', 'Функциональная диагностика', 4),
('endo', 'Эндоскопия', 5);
INSERT INTO public.diagnostics_symptoms (name, recommendation, sort_order) VALUES
('Боли в животе', 'Рекомендуем: УЗИ брюшной полости, ФГДС, общий анализ крови.', 1),
('Головные боли', 'Обратитесь к специалисту для подбора исследования.', 2),
('Отдышка', 'Рекомендуем: рентген или КТ грудной клетки, ЭКГ, спирометрия.', 3),
('Учащённый пульс', 'Рекомендуем: ЭКГ, холтеровское мониторирование, ЭхоКГ.', 4),
('Боли в груди', 'Рекомендуем: ЭКГ, УЗИ сердца (ЭхоКГ), рентген грудной клетки.', 5),
('Слабость и усталость', 'Рекомендуем: общий и биохимический анализ крови, гормоны щитовидной железы.', 6),
('Повышенное давление', 'Рекомендуем: суточный мониторинг АД, ЭКГ, УЗИ почек.', 7),
('Боли в суставах', 'Рекомендуем: УЗИ суставов, рентген, денситометрия.', 8),
('Кашель', 'Рекомендуем: флюорография или рентген лёгких, при необходимости КТ.', 9),
('Проблемы со сном', 'Рекомендуем: консультация терапевта, гормональные исследования, ЭКГ.', 10),
('Тошнота', 'Рекомендуем: ФГДС (гастроскопия), УЗИ брюшной полости.', 11),
('Отёки', 'Рекомендуем: анализы мочи и крови, УЗИ почек, ЭКГ.', 12),
('Головокружение', 'Обратитесь к специалисту для подбора исследования.', 13),
('Боли в пояснице', 'Обратитесь к специалисту для подбора исследования.', 14),
('Нарушение зрения', 'Обратитесь к специалисту для подбора исследования.', 15),
('Онемение конечностей', 'Обратитесь к специалисту для подбора исследования.', 16);
INSERT INTO public.diagnostics_items (slug, title, subtitle, category_key, icon, price, badge, body, includes, preparation, sort_order) VALUES
('kt', 'Компьютерная томография (КТ)', 'Послойное исследование органов и костей с высокой точностью', 'xray', 'Scan', 'от 3500 сом', 'Экспертный класс', 'КТ — послойное рентгеновское исследование органов, костей и сосудов с высокой детализацией. Помогает быстро поставить точный диагноз при травмах, заболеваниях лёгких, брюшной полости и опорно-двигательного аппарата.', 'Исследование на аппарате экспертного класса, Заключение врача-рентгенолога, Снимки и описание на диске или в электронном виде', 'Специальной подготовки обычно не требуется. При исследовании с контрастом — не есть за 4 часа и взять с собой результаты предыдущих исследований.', 1),
('rentgen', 'Рентген', 'Быстрая диагностика костей и органов грудной клетки', 'xray', 'Bone', 'от 700 сом', NULL, 'Рентген — быстрый способ оценить состояние костей, суставов и органов грудной клетки. Исследование занимает несколько минут.', 'Снимок в одной или двух проекциях, Заключение врача-рентгенолога', 'Специальной подготовки не требуется. Снимите металлические украшения в зоне исследования.', 3),
('mammografiya', 'Маммография', 'Скрининг здоровья молочных желёз', 'xray', 'HeartPulse', 'от 1200 сом', 'Скрининг', 'Маммография — рентгеновское исследование молочных желёз для раннего выявления изменений. Рекомендуется женщинам старше 40 лет ежегодно.', 'Исследование обеих молочных желёз, Заключение врача', 'Проводится на 5–12 день цикла. Не используйте дезодорант и крем в день исследования.', 4),
('flyuorografiya', 'Флюорография', 'Профилактическое исследование лёгких', 'xray', 'Wind', 'от 500 сом', NULL, 'Флюорография — профилактическое исследование органов грудной клетки для выявления заболеваний лёгких на ранней стадии.', 'Снимок органов грудной клетки, Заключение врача', 'Подготовка не требуется.', 5),
('densitometriya', 'Денситометрия', 'Оценка плотности костной ткани', 'xray', 'Bone', 'от 1800 сом', NULL, 'Денситометрия — исследование плотности костной ткани для диагностики остеопороза и оценки риска переломов.', 'Измерение плотности кости в ключевых зонах, Заключение врача', 'Не принимайте препараты кальция за 24 часа до исследования.', 6),
('uzi-bryushnoy-polosti', 'УЗИ брюшной полости', 'Печень, желчный пузырь, поджелудочная, селезёнка', 'uzi', 'Waves', 'от 1200 сом', NULL, 'УЗИ брюшной полости — безопасная оценка печени, желчного пузыря, поджелудочной железы, селезёнки и почек.', 'УЗИ органов брюшной полости, Заключение врача-узиста', 'Натощак: не есть за 6–8 часов, не пить газированные напитки. За 2–3 дня исключить продукты, вызывающие газообразование.', 7),
('uzi-serdtsa-ehokg', 'УЗИ сердца (ЭхоКГ)', 'Оценка работы сердца и клапанов', 'uzi', 'HeartPulse', 'от 1800 сом', NULL, 'ЭхоКГ — ультразвуковое исследование сердца: размеры камер, работа клапанов, сократимость миокарда и кровоток.', 'УЗИ сердца с допплером, Заключение врача', 'Специальной подготовки не требуется.', 8),
('uzi-shchitovidnoy-zhelezy', 'УЗИ щитовидной железы', 'Узлы, объём и структура железы', 'uzi', 'Activity', 'от 900 сом', NULL, 'УЗИ щитовидной железы — оценка структуры, объёма и образований железы. Рекомендуется при изменениях анализов на гормоны.', 'УЗИ щитовидной железы и регионарных лимфоузлов, Заключение врача', 'Подготовка не требуется.', 9),
('uzi-pochek', 'УЗИ почек и мочевого пузыря', 'Диагностика мочевыделительной системы', 'uzi', 'Droplets', 'от 1000 сом', NULL, 'УЗИ почек и мочевого пузыря — оценка мочевыделительной системы, выявление камней, кист и воспалительных изменений.', 'УЗИ почек и мочевого пузыря, Заключение врача', 'За час до исследования выпить 0,5–1 л негазированной воды, не мочиться.', 10),
('uzi-v-ginekologii', 'УЗИ в гинекологии', 'Матка, яичники, контроль беременности', 'uzi', 'Stethoscope', 'от 1200 сом', NULL, 'Гинекологическое УЗИ — оценка матки, яичников и контроль беременности на любом сроке.', 'УЗИ органов малого таза, Заключение врача', 'При трансабдоминальном исследовании — наполненный мочевой пузырь (выпить 1 л воды за час).', 11),
('uzi-detyam', 'УЗИ детям', 'Бережная диагностика с первых дней жизни', 'uzi', 'Baby', 'от 1000 сом', 'Для детей', 'Детское УЗИ — безопасная и безболезненная диагностика с первых дней жизни: нейросонография, УЗИ брюшной полости, почек и тазобедренных суставов.', 'УЗИ по показаниям педиатра, Заключение врача', 'Желательно, чтобы ребёнок был спокоен и накормлен (кроме УЗИ брюшной полости — натощак).', 12),
('uzdg-sosudov', 'УЗДГ сосудов', 'Кровоток в сосудах головы, шеи и конечностей', 'uzi', 'Waves', 'от 1500 сом', NULL, 'УЗДГ — оценка кровотока в сосудах головы, шеи, рук и ног. Выявляет сужение сосудов и нарушения кровообращения.', 'Дуплексное сканирование сосудов, Заключение врача', 'В день исследования исключить кофе, чай и курение за 2 часа.', 13),
('uzi-sustavov', 'УЗИ суставов и мягких тканей', 'Связки, мышцы, суставные сумки', 'uzi', 'Bone', 'от 1100 сом', NULL, 'УЗИ суставов — оценка связок, мышц, сухожилий и суставных сумок при травмах и воспалениях.', 'УЗИ одного сустава, Заключение врача', 'Подготовка не требуется.', 14),
('obshchiy-analiz-krovi', 'Общий анализ крови', 'Базовое исследование с расшифровкой', 'lab', 'TestTube', 'от 350 сом', 'Результат за 1 день', 'Общий анализ крови — базовое исследование: гемоглобин, лейкоциты, тромбоциты, СОЭ. Помогает выявить воспаление, анемию и другие изменения.', 'Забор крови, Полный развёрнутый анализ, Расшифровка результата', 'Сдавать натощак или через 3–4 часа после еды.', 15),
('biokhimiya-krovi', 'Биохимия крови', 'Печень, почки, обмен веществ', 'lab', 'FlaskConical', 'от 900 сом', NULL, 'Биохимический анализ крови — оценка работы печени, почек, углеводного и липидного обмена.', 'Забор крови, Развёрнутая биохимическая панель, Расшифровка результата', 'Строго натощак (8–12 часов без еды), можно пить воду.', 16),
('gormonalnye-issledovaniya', 'Гормональные исследования', 'Щитовидная железа, репродуктивные гормоны', 'lab', 'Activity', 'от 600 сом', NULL, 'Анализы на гормоны — оценка щитовидной железы, репродуктивной системы и надпочечников.', 'Забор крови, Исследование выбранных гормонов, Расшифровка результата', 'Натощак, утром. За день исключить стрессы и физические нагрузки.', 17),
('pcr-i-infekcii', 'ПЦР и инфекции', 'Точное выявление возбудителя', 'lab', 'Microscope', 'от 800 сом', NULL, 'ПЦР-диагностика — точное выявление возбудителей инфекций по ДНК/RNA.', 'Забор материала, ПЦР-исследование, Расшифровка результата', 'Зависит от вида исследования — уточните у администратора.', 18),
('analizy-mochi', 'Анализы мочи', 'Общий анализ, проба Нечипоренко', 'lab', 'Droplets', 'от 300 сом', NULL, 'Анализы мочи — оценка работы почек и мочевыводящих путей.', 'Общий анализ мочи, При необходимости — проба Нечипоренко, Расшифровка результата', 'Собрать утреннюю порцию мочи в чистый контейнер после гигиенических процедур.', 19),
('onkomarkery', 'Онкомаркеры', 'Раннее выявление и контроль лечения', 'lab', 'Microscope', 'от 900 сом', NULL, 'Онкомаркеры — исследование крови на специфические белки для скрининга и контроля лечения.', 'Забор крови, Исследование выбранных маркеров, Расшифровка результата', 'Натощак (4–6 часов без еды).', 20),
('ekg', 'ЭКГ', 'Электрокардиограмма с расшифровкой врача', 'funk', 'Activity', 'от 500 сом', NULL, 'ЭКГ — регистрация электрической активности сердца: ритм, проводимость, признаки ишемии.', 'Снятие ЭКГ в 12 отведениях, Расшифровка врачом', 'За 2 часа исключить кофе и курение, перед исследованием отдохнуть 10 минут.', 21),
('holter', 'Холтеровское мониторирование', 'Суточный контроль сердца и давления', 'funk', 'HeartPulse', 'от 2500 сом', NULL, 'Холтер — суточная запись ЭКГ и/или артериального давления в привычном ритме жизни.', 'Установка регистратора, Суточная запись, Расшифровка и заключение врача', 'Наденьте удобную одежду. Ведите дневник активности и симптомов.', 22),
('spirometriya', 'Спирометрия', 'Исследование функции дыхания', 'funk', 'Wind', 'от 800 сом', NULL, 'Спирометрия — оценка объёмов и скоростей дыхания для диагностики астмы, ХОБЛ и других заболеваний лёгких.', 'Исследование функции внешнего дыхания, Заключение врача', 'За 4 часа не курить, за 2 часа не есть плотно. Возьмите с собой ингалятор, если пользуетесь.', 23),
('fgds', 'ФГДС (гастроскопия)', 'Осмотр желудка и двенадцатиперстной кишки', 'endo', 'Stethoscope', 'от 2200 сом', 'Комфортно', 'ФГДС — эндоскопический осмотр пищевода, желудка и двенадцатиперстной кишки. Возможно проведение с седацией.', 'Эндоскопическое исследование, При необходимости — биопсия, Заключение врача', 'Строго натощак (8–10 часов без еды и воды).', 24),
('kolonoskopiya', 'Колоноскопия', 'Осмотр толстой кишки', 'endo', 'Stethoscope', 'от 4500 сом', NULL, 'Колоноскопия — эндоскопическое исследование толстой кишки для выявления воспалений, полипов и других изменений.', 'Эндоскопическое исследование, При необходимости — биопсия, Заключение врача', 'За 2–3 дня — бесшлаковая диета, накануне — очищение кишечника по схеме врача.', 25);